#include <stdio.h>
#include <stdlib.h>

/* Simple One-Pass Translator for Addition/Subtraction Expressions */
int lookahead;
void expr();
void term();
void match(int t);

void next_token() {
    lookahead = getchar();
}

void match(int t) {
    if (lookahead == t)
        next_token();
    else {
        printf("Syntax Error\n");
        exit(1);
    }
}

void term() {
    if (lookahead >= '0' && lookahead <= '9') {
        printf("MOV R0, %c\n", lookahead);
        match(lookahead);
    } else {
        printf("Syntax error: expected digit\n");
        exit(1);
    }
}

void expr() {
    term();
    while (lookahead == '+' || lookahead == '-') {
        int op = lookahead;
        match(op);
        term();
        if (op == '+') printf("ADD R0, R1\n");
        else printf("SUB R0, R1\n");
    }
}

int main() {
    printf("Enter expression (e.g., 3+4-2): ");
    next_token();
    expr();
    printf("Compilation complete in one pass.\n");
    return 0;
}

