void mark_reachable(int start, int num_states, int trans[][2], bool visited[]) {
    int queue[100], front = 0, rear = 0;
    queue[rear++] = start;
    visited[start] = true;
    while(front < rear) {
        int curr = queue[front++];
        for(int i = 0; i < 2; i++) {
            int next = trans[curr][i];
            if(next != -1 && !visited[next]) {
                visited[next] = true;
                queue[rear++] = next;
            }
        }
    }
}

