// Node representing attribute space in an AST
typedef struct Node {
    int val; // synthesized attribute
    struct Node *left, *right;
} Node;

Node* createNode(int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->val = val;
    n->left = n->right = NULL;
    return n;
}

// Recursive evaluator for evaluating attribute space bottom-up
int evaluateAST(Node* root) {
    if (!root) return 0;
    if (!root->left && !root->right) return root->val; // base case

    int l_val = evaluateAST(root->left);
    int r_val = evaluateAST(root->right);

    root->val = l_val + r_val; // Synthesizing attribute
    return root->val;
}

int main() {
