Sethi-Ullman Labeling rule for node N with children L and R:
if label(L) == label(R): label(N) = label(L) + 1
else: label(N) = max(label(L), label(R))

code.src:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Node structure for expression tree
typedef struct Node {
    char op;
    int val;
    struct Node *left, *right;
    int label;
} Node;

Node* createNode(char op, int val, Node* l, Node* r) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->op = op;
    n->val = val;
    n->left = l;
    n->right = r;
    n->label = 0;
    return n;
}

// Compute Sethi-Ullman labels
void computeLabels(Node* root) {
    if (!root) return;
    if (!root->left && !root->right) {
        root->label = 1; // Leaf node
        return;
    }
    computeLabels(root->left);
    computeLabels(root->right);
    if (root->left->label == root->right->label)
        root->label = root->left->label + 1;
    else
        root->label = (root->left->label > root->right->label) ? root->left->label : root->right->label;
}

int main() {
    // Expression: (a + b) * (c + d)
    Node* root = createNode('*', 0,
                    createNode('+', 0, createNode('0', 1, NULL, NULL), createNode('0', 2, NULL, NULL)),
                    createNode('+', 0, createNode('0', 3, NULL, NULL), createNode('0', 4, NULL, NULL)));
    computeLabels(root);
    printf("Root minimum registers required: %d\n", root->label);
    return 0;
}

